// Verify the payment provider's webhook signature before trusting a single field.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and N8N_BLOCK_ENV_ACCESS_IN_NODE=false
// on the n8n container (both are set in infra/docker-compose.yml).
const crypto = require('crypto');

const secret = $env.PAYMENT_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('PAYMENT_WEBHOOK_SECRET is not set on this n8n instance');
}

const results = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const signatureHeader = headers['x-provider-signature'] || headers['stripe-signature'] || '';

  // The Webhook node runs with "Raw Body" on, so the exact bytes the provider
  // signed are in binary.data - not in the parsed JSON body. Re-serialising the
  // parsed body would change key order and break the HMAC.
  const rawBody = item.binary && item.binary.data && item.binary.data.data
    ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
    : JSON.stringify(item.json.body || {});

  // Header format: t=<unix seconds>,v1=<hex hmac of "<t>.<rawBody>">
  const parts = {};
  for (const pair of String(signatureHeader).split(',')) {
    const [k, v] = pair.split('=');
    if (k && v) parts[k.trim()] = v.trim();
  }

  if (!parts.t || !parts.v1) {
    throw new Error('Missing or malformed signature header - request rejected');
  }

  const ageSeconds = Math.abs(Math.floor(Date.now() / 1000) - Number(parts.t));
  if (ageSeconds > 300) {
    throw new Error('Signature timestamp is ' + ageSeconds + 's old - replay rejected');
  }

  const expected = crypto
    .createHmac('sha256', secret)
    .update(parts.t + '.' + rawBody)
    .digest('hex');

  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(parts.v1, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('Webhook signature did not match - request rejected');
  }

  const event = JSON.parse(rawBody);
  const object = (event.data && event.data.object) || {};
  const metadata = object.metadata || {};

  // Only paid/succeeded events reach the enrolment path. Anything else is a
  // configuration mistake in the provider dashboard and should be loud, not silent.
  const PAID_EVENTS = ['invoice.paid', 'checkout.session.completed', 'payment_intent.succeeded'];
  if (!PAID_EVENTS.includes(event.type)) {
    throw new Error('Unexpected event type on the enrolment webhook: ' + event.type);
  }

  const fullName = String(object.customer_name || metadata.student_name || '').trim();
  const nameParts = fullName ? fullName.split(/\s+/) : [];

  results.push({
    json: {
      provider: $env.PAYMENT_PROVIDER_NAME || 'payment-provider',
      event_id: event.id,
      event_type: event.type,
      email: String(object.customer_email || object.email || metadata.email || '')
        .toLowerCase()
        .trim(),
      first_name: nameParts[0] || 'Student',
      last_name: nameParts.slice(1).join(' ') || '-',
      customer_id: object.customer || null,
      invoice_id: object.invoice || object.id || null,
      amount_cents: object.amount_total || object.amount_paid || object.amount_due || object.amount || null,
      currency: object.currency || null,
      course_id: metadata.course_id || $env.DEFAULT_COURSE_ID,

      raw: event,
    },
  });
}

return results;

// "Already enrolled" is the state we were trying to reach, so it is a success.
// Note: neverError only suppresses HTTP status errors. Timeouts, DNS failures and
// socket resets still throw, so retryOnFail on the previous node is still doing work.
const response = $input.first().json;
const status = Number(response.statusCode);
const body = response.body || {};
const asText = JSON.stringify(body).toLowerCase();

if (status >= 200 && status < 300) {
  return [{ json: { enrolment_id: body.id || null, state: 'created', http_status: status } }];
}

const alreadyEnrolled =
  status === 422 && /already\s*enroll|has\s*already|duplicate/.test(asText);

if (alreadyEnrolled) {
  return [{ json: { enrolment_id: body.id || null, state: 'already_enrolled', http_status: status } }];
}

// Anything else is a real failure. Throwing here routes to the error output and
// leaves processed_events at status 'received', which the nightly reconciliation
// workflow (04) picks up as a payment without an enrolment.
throw new Error(
  'Enrolment failed with HTTP ' + status + ': ' + JSON.stringify(body).slice(0, 500),
);

